#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/homebrew/tasks/upgrade-brew.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Upgrade all tools managed using Homebrew"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

import os
import shutil
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def exit_code(rc):
  """The exit code of the shell for a return code of subprocess."""
  return 128 - rc if rc < 0 else rc


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(exit_code(rc))


def main():
  helpers.print_header("Homebrew packages ...")

  # Check if brew is installed before attempting to update
  if not shutil.which("brew"):
    helpers.print_error("Homebrew is not installed. Please install Homebrew first.")
    sys.exit(1)

  # Update Homebrew itself
  helpers.print_subheader("Updating Homebrew ...")
  run("brew", "update", "--force")  # --verbose

  # Formulae, casks and mas apps are mise's: [mise.bootstrap.packages] in
  # tools.toml, generated into conf.d/<tool>/mise.toml. VS Code extensions are
  # brew's (Brewfile, via brew:casks).

  # Tailscale runs as a root service and needs special handling before the
  # generic upgrade below would otherwise fail on its root-owned keg.
  rc = helpers.run_task_if_exists("upgrade:tailscale")
  if rc:
    sys.exit(exit_code(rc))

  helpers.print_subheader("Deleting brew packages NOT in [bootstrap.packages] ...")
  run("mise", "bootstrap", "packages", "prune", "--yes")

  helpers.print_subheader("Install/Upgrade all declared packages ...")
  run("mise", "bootstrap", "packages", "upgrade", "--yes")
  run("mise", "bootstrap", "packages", "apply", "--update", "--yes")

  # mise run brew:casks

  # # Remove unused dependencies
  # helpers.print_subheader("Removing unused Homebrew dependencies ...")
  # brew autoremove

  # # Cleanup old versions of packages
  # helpers.print_subheader("Cleaning up old Homebrew packages ...")
  # brew cleanup --prune=all


if __name__ == "__main__":
  main()
